"use client";
import "./styles/skeuo-key-button.css";

import type { ButtonHTMLAttributes, ReactNode } from "react";
/** The portfolio tech-stack key: a recessed face inside a thick key base. */
export function SkeuoKeyButton({ children, icon, tone = "neutral", className = "", ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { icon?: ReactNode; tone?: "neutral" | "accent" | "cobalt" }) {
  return <span data-sk-root="" className={`sk-tech-key ${className}`} data-tone={tone}><button {...props} type={props.type ?? "button"} className="sk-tech-key-face">{icon && <span className="sk-tech-socket">{icon}</span>}{children}</button></span>;
}

@import "./skeuo-base.css";
.sk-tech-key{--sk-key-highlight:var(--sk-highlight);display:inline-block;width:142px;height:60px;flex-shrink:0;padding:4px 4px 9px;border:1px solid var(--sk-key-edge);border-radius:10px;background:var(--sk-key-base);box-shadow:0 2px 0 color-mix(in srgb,var(--sk-ink) 25%,var(--sk-bg)),0 4px 5px #00000012;}
.sk-tech-key-face{display:flex;align-items:center;justify-content:center;gap:9px;width:100%;height:100%;padding-inline:8px;border:1px solid var(--sk-key-edge);border-radius:6px;background:var(--sk-key);color:var(--sk-ink);box-shadow:inset 0 3px 5px #00000035,inset 0 -1px var(--sk-key-highlight),0 2px 2px #00000012;font-size:12px;font-weight:500;cursor:pointer;transition:transform .18s,box-shadow .18s;}
.sk-tech-socket{display:grid;place-items:center;width:29px;height:29px;flex-shrink:0;border:1px solid color-mix(in srgb,var(--sk-key-edge) 75%,transparent);border-radius:5px;box-shadow:inset 0 2px 3px #00000030,0 1px color-mix(in srgb,var(--sk-key-highlight) 65%,transparent);}
.sk-tech-key[data-tone="accent"]{--sk-key:var(--sk-accent);--sk-key-base:var(--sk-accent-base);--sk-key-edge:var(--sk-accent-edge);--sk-key-highlight:color-mix(in srgb,var(--sk-accent-bright) 70%,#fff);}
.sk-tech-key[data-tone="accent"] .sk-tech-key-face{color:var(--sk-accent-ink);}
.sk-tech-key:hover .sk-tech-key-face{transform:translateY(1px);}
.sk-tech-key-face:active{transform:translateY(4px);box-shadow:inset 0 4px 7px #00000055,inset 0 -1px var(--sk-key-highlight);}
@media(prefers-reduced-motion:reduce){.sk-tech-key-face{transition:none;}}
.sk-tech-key:has(button:disabled){opacity:.5;}
.sk-tech-key button:disabled{cursor:not-allowed;}
.sk-tech-key[data-tone="cobalt"]{--sk-key:#2457e6;--sk-key-base:#17399b;--sk-key-edge:#1744bd;--sk-key-highlight:#789aff;}
.sk-tech-key[data-tone="cobalt"] .sk-tech-key-face{color:#fff;}
.sk-tech-key-face{white-space:nowrap;}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root] :focus-visible) {outline:2px solid var(--sk-accent);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Namespaced defaults. Host applications can override any --sk-* token. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper:#faf9f5;--sk-album-ink:#45423b;--sk-album-edge:#c4c2ba;--sk-album-base:#d6d4ca;
  --sk-bg: #fff; --sk-ink: #202020; --sk-muted: #777774; --sk-line: #e7e7e4;
  --sk-surface: #f5f5f2; --sk-surface-raised: #fafaf8; --sk-well: #e9e9e5;
  --sk-edge: #d1d1cb; --sk-highlight: #fff; --sk-base: #d9d9d3; --sk-shadow: #00000017;
  --sk-accent: #365e50; --sk-accent-bright: #487b68; --sk-accent-base: #213c32; --sk-accent-edge: #294b3e; --sk-accent-ink: #fff;
  --sk-key: #f9f9f7; --sk-key-edge: #c6c7c1; --sk-key-base: #d0d1ca;
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper:#272728;--sk-album-ink:#d0cfca;--sk-album-edge:#555456;--sk-album-base:#111214;
  --sk-bg: #000; --sk-ink: #efefeb; --sk-muted: #92928d; --sk-line: #242424;
  --sk-surface: #191919; --sk-surface-raised: #252525; --sk-well: #111;
  --sk-edge: #3b3b39; --sk-highlight: #ffffff1e; --sk-base: #080808; --sk-shadow: #00000099;
  --sk-accent: #9ab5a6; --sk-accent-bright: #bbcec2; --sk-accent-base: #4d6558; --sk-accent-edge: #6f8a79; --sk-accent-ink: #14251c;
  --sk-key: #292a29; --sk-key-edge: #484946; --sk-key-base: #101110;

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper:#272728;--sk-album-ink:#d0cfca;--sk-album-edge:#555456;--sk-album-base:#111214;
  --sk-bg: #000; --sk-ink: #efefeb; --sk-muted: #92928d; --sk-line: #242424;
  --sk-surface: #191919; --sk-surface-raised: #252525; --sk-well: #111;
  --sk-edge: #3b3b39; --sk-highlight: #ffffff1e; --sk-base: #080808; --sk-shadow: #00000099;
  --sk-accent: #9ab5a6; --sk-accent-bright: #bbcec2; --sk-accent-base: #4d6558; --sk-accent-edge: #6f8a79; --sk-accent-ink: #14251c;
  --sk-key: #292a29; --sk-key-edge: #484946; --sk-key-base: #101110;

} }
